test_that("built-in formats list every field of the station", {
  n <- station_format("nedap")
  f <- station_format("fire")
  expect_setequal(n$field, station_fields("nedap"))
  expect_setequal(f$field, station_fields("fire"))
  expect_equal(f[required == TRUE, field], station_required("fire"))
  expect_false(anyNA(f$description))
})

test_that("a written template reads back as the same format", {
  file <- withr::local_tempfile(fileext = ".txt")
  suppressMessages(station_format("nedap", file = file))
  expect_true(startsWith(readLines(file, n = 1L), "#"))
  back <- as_station_format(file, "nedap")
  expect_equal(back[, .(field, column, unit)], builtin_format("nedap"))
})
